import{describe,it,expect}from"vitest";import Core from"../../frontend/js-modules/map3d-core.js";describe("map3d-core: projection",()=>{it("projects the reference origin to [0, 0]",()=>{const[e,t]=Core.project(Core.PROJECTION_ORIGIN.lng,Core.PROJECTION_ORIGIN.lat);expect(e).toBeCloseTo(0,6),expect(t).toBeCloseTo(0,6)}),it("project/unproject round-trips for a real city coordinate",()=>{const e=77.209,t=28.6139,[o,r]=Core.project(e,t),[i,n]=Core.unproject(o,r);expect(i).toBeCloseTo(e,6),expect(n).toBeCloseTo(t,6)}),it("moves east/north consistently in sign",()=>{const[e]=Core.project(Core.PROJECTION_ORIGIN.lng+1,Core.PROJECTION_ORIGIN.lat),[,t]=Core.project(Core.PROJECTION_ORIGIN.lng,Core.PROJECTION_ORIGIN.lat+1);expect(e).toBeGreaterThan(0),expect(t).toBeGreaterThan(0)})}),describe("map3d-core: haversineKm",()=>{it("returns 0 for identical points",()=>{expect(Core.haversineKm(28.6139,77.209,28.6139,77.209)).toBeCloseTo(0,6)}),it("returns a realistic distance between Delhi and Agra (~190-240km)",()=>{const e=Core.haversineKm(28.6139,77.209,27.1767,78.0081);expect(e).toBeGreaterThan(150),expect(e).toBeLessThan(260)}),it("is symmetric",()=>{const e=Core.haversineKm(28.6139,77.209,27.1767,78.0081),t=Core.haversineKm(27.1767,78.0081,28.6139,77.209);expect(e).toBeCloseTo(t,9)})}),describe("map3d-core: nearestDestinations",()=>{const e=[{id:"a",lat:28.6139,lng:77.209},{id:"b",lat:27.1767,lng:78.0081},{id:"c",lat:26.9124,lng:75.7873},{id:"d",lat:15.2993,lng:74.124}];it("excludes the origin itself",()=>{const t=Core.nearestDestinations(e[0],e,3);expect(t.some(e=>"a"===e.destination.id)).toBe(!1)}),it("sorts nearest-first",()=>{const t=Core.nearestDestinations(e[0],e,3).map(e=>e.distanceKm);expect(t).toEqual([...t].sort((e,t)=>e-t))}),it("respects the count limit",()=>{const t=Core.nearestDestinations(e[0],e,2);expect(t.length).toBe(2)}),it("defaults to 5 when count is omitted",()=>{const e=Array.from({length:8},(e,t)=>({id:`x${t}`,lat:20+t,lng:70+t})),t=Core.nearestDestinations({id:"origin",lat:20,lng:70},e,void 0);expect(t.length).toBe(5)})}),describe("map3d-core: clusterDestinations",()=>{const e=[{id:"a",lat:28.61,lng:77.2},{id:"b",lat:28.62,lng:77.21},{id:"c",lat:15.29,lng:74.12}];it("with cellSize 0 returns one cluster per destination",()=>{const t=Core.clusterDestinations(e,0);expect(t.length).toBe(3),expect(t.every(e=>1===e.count)).toBe(!0)}),it("with a large cellSize, groups nearby points together",()=>{const t=Core.clusterDestinations(e,10),o=t.reduce((e,t)=>e+t.count,0);expect(o).toBe(3),expect(t.some(e=>e.count>=2)).toBe(!0)}),it("cluster centroid is the average position of its members",()=>{const e=[{id:"a",lat:28.6,lng:77.2},{id:"b",lat:28.6,lng:77.22}],t=Core.clusterDestinations(e,50);expect(t.length).toBe(1);const[o,r]=e.map(e=>Core.project(e.lng,e.lat));expect(t[0].x).toBeCloseTo((o[0]+r[0])/2,6),expect(t[0].y).toBeCloseTo((o[1]+r[1])/2,6)})}),describe("map3d-core: cellSizeForZoom",()=>{it("returns 0 (no clustering) when fully zoomed in",()=>{expect(Core.cellSizeForZoom(10)).toBe(0)}),it("increases cell size as camera distance grows",()=>{const e=Core.cellSizeForZoom(20),t=Core.cellSizeForZoom(45),o=Core.cellSizeForZoom(60);expect(t).toBeGreaterThan(e),expect(o).toBeGreaterThan(t)})}),describe("map3d-core: filterByCategory",()=>{const e=[{id:"a",categories:["beaches","adventure"]},{id:"b",categories:["mountains"]},{id:"c",categories:["heritage","historical"]}];it("returns all destinations when no categories are active",()=>{expect(Core.filterByCategory(e,new Set)).toEqual(e)}),it("filters to destinations matching any active category",()=>{const t=Core.filterByCategory(e,new Set(["mountains"]));expect(t.map(e=>e.id)).toEqual(["b"])}),it("matches on OR semantics across multiple active categories",()=>{const t=Core.filterByCategory(e,new Set(["mountains","beaches"]));expect(t.map(e=>e.id).sort()).toEqual(["a","b"])})}),describe("map3d-core: filterByBookmarks",()=>{const e=[{id:"a"},{id:"b"},{id:"c"}];it("returns only bookmarked destinations",()=>{const t=Core.filterByBookmarks(e,new Set(["b"]));expect(t.map(e=>e.id)).toEqual(["b"])}),it("returns an empty array when nothing is bookmarked",()=>{expect(Core.filterByBookmarks(e,new Set)).toEqual([])})});